param(
    [Parameter(Mandatory=$true)][string]$PreviewDirectory,
    [string]$PreviewFile = 'comparison.html',
    [string]$Chrome = 'C:\Program Files\Google\Chrome\Application\chrome.exe'
)
# Run only against the disposable synthetic HTML generated by the regression test.
$ErrorActionPreference = 'Stop'
$fixture = Join-Path $PreviewDirectory $PreviewFile
if (!(Test-Path -LiteralPath $fixture)) { throw 'Generate the synthetic --preview fixture first.' }
$fixtureUri = ([System.Uri](Resolve-Path -LiteralPath $fixture).Path).AbsoluteUri
if (!$fixtureUri.StartsWith('file:')) { throw 'Only a local synthetic fixture is supported.' }
$listener = [System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Loopback, 0)
$listener.Start()
$debugPort = $listener.LocalEndpoint.Port
$listener.Stop()
$profile = Join-Path $PreviewDirectory ('cdp-' + [Guid]::NewGuid().ToString('N'))
$browserProcess = Start-Process -FilePath $Chrome -WindowStyle Hidden -PassThru -ArgumentList @('--headless','--no-sandbox','--disable-gpu','--disable-background-networking','--no-first-run','--no-default-browser-check',"--remote-debugging-port=$debugPort",'--remote-debugging-address=127.0.0.1',"--user-data-dir=`"$profile`"",'about:blank')
$socket = $null
try {
    $tabs = $null
    for($attempt=0; $attempt -lt 30; $attempt++) {
        try { $tabs = Invoke-RestMethod "http://127.0.0.1:$debugPort/json"; break } catch { Start-Sleep -Milliseconds 200 }
    }
    if (!$tabs) { throw 'Browser debugging connection unavailable.' }
    $tab = $tabs | Where-Object { $_.type -eq 'page' } | Select-Object -First 1
    $socket = [System.Net.WebSockets.ClientWebSocket]::new()
    $null = $socket.ConnectAsync([Uri]$tab.webSocketDebuggerUrl, [Threading.CancellationToken]::None).GetAwaiter().GetResult()
    $script:commandId = 0
    function Invoke-Cdp([string]$Method, [hashtable]$Arguments = @{}) {
        $script:commandId++
        $message = @{id=$script:commandId; method=$Method; params=$Arguments} | ConvertTo-Json -Depth 20 -Compress
        $bytes = [Text.Encoding]::UTF8.GetBytes($message)
        $null = $socket.SendAsync([ArraySegment[byte]]::new($bytes), [Net.WebSockets.WebSocketMessageType]::Text, $true, [Threading.CancellationToken]::None).GetAwaiter().GetResult()
        do {
            $stream = [IO.MemoryStream]::new()
            $buffer = New-Object byte[] 65536
            do {
                $deadline = [Threading.CancellationTokenSource]::new(15000)
                try { $received = $socket.ReceiveAsync([ArraySegment[byte]]::new($buffer), $deadline.Token).GetAwaiter().GetResult() } finally { $deadline.Dispose() }
                $stream.Write($buffer, 0, $received.Count)
            } while (!$received.EndOfMessage)
            $response = [Text.Encoding]::UTF8.GetString($stream.ToArray()) | ConvertFrom-Json
            $stream.Dispose()
        } while ($response.id -ne $script:commandId)
        if ($response.error) { throw ($response.error | ConvertTo-Json -Compress) }
        if ($response.result.exceptionDetails) { throw ($response.result.exceptionDetails | ConvertTo-Json -Depth 10 -Compress) }
        return $response.result
    }
    $null = Invoke-Cdp 'Page.enable'
    $null = Invoke-Cdp 'Page.navigate' @{url=$fixtureUri}
    for($attempt=0; $attempt -lt 30; $attempt++) {
        $loaded = Invoke-Cdp 'Runtime.evaluate' @{expression='document.readyState'; returnByValue=$true}
        if ($loaded.result.value -eq 'complete') { break }
        Start-Sleep -Milliseconds 100
    }
    foreach($viewport in @(@{name='desktop'; width=1440; height=1000}, @{name='phone'; width=390; height=844})) {
        $null = Invoke-Cdp 'Emulation.setDeviceMetricsOverride' @{width=$viewport.width; height=$viewport.height; deviceScaleFactor=1; mobile=$false}
        $null = Invoke-Cdp 'Runtime.evaluate' @{expression='scrollTo(0,0)'}
        $compareButton = Invoke-Cdp 'Runtime.evaluate' @{expression='(()=>{const a=document.querySelector(".waec-compare-link"); if(!a)return null; const r=a.getBoundingClientRect(); return {href:a.getAttribute("href"),fits:r.left>=0&&r.right<=innerWidth&&a.scrollWidth<=a.clientWidth+1,touch:r.height>=44,copy:!!a.querySelector(".waec-compare-copy strong"),color:getComputedStyle(a).color};})()'; returnByValue=$true}
        if ($null -ne $compareButton.result.value) {
            $button = $compareButton.result.value
            if ($button.href -ne 'waec-comparison.php' -or !$button.fits -or !$button.touch -or !$button.copy -or $button.color -ne 'rgb(22, 78, 80)') { throw 'Compare batches link layout, destination or contrast check failed.' }
            Write-Output "$($viewport.name): Compare batches button fits, retains its destination and has readable text styling."
        }
        $size = Invoke-Cdp 'Runtime.evaluate' @{expression='JSON.stringify({viewport:innerWidth,document:document.documentElement.scrollWidth})'; returnByValue=$true}
        $dimensions = $size.result.value | ConvertFrom-Json
        if ($dimensions.document -gt ($dimensions.viewport+1)) { throw "Horizontal page overflow at $($viewport.name): $($size.result.value)" }
        $capture = Invoke-Cdp 'Page.captureScreenshot' @{format='png'; captureBeyondViewport=$false}
        [IO.File]::WriteAllBytes((Join-Path $PreviewDirectory ($viewport.name+'-checked.png')), [Convert]::FromBase64String($capture.data))
        Write-Output "$($viewport.name): no page overflow ($($dimensions.viewport)px)."
        $loginDialog = Invoke-Cdp 'Runtime.evaluate' @{expression='!!document.querySelector("dialog#old-student-login")'; returnByValue=$true}
        if ($loginDialog.result.value) {
            $null = Invoke-Cdp 'Runtime.evaluate' @{expression='document.querySelector("button[data-open-login]").click()'}
            $state = Invoke-Cdp 'Runtime.evaluate' @{expression='(()=>{const d=document.getElementById("old-student-login"),r=d.getBoundingClientRect();return d.open&&d.matches(":modal")&&document.activeElement.id==="old-student-identity"&&r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight;})()'; returnByValue=$true}
            if (!$state.result.value) { throw 'Login modal did not open, focus its input, or fit the screen.' }
            for($tabIndex=0; $tabIndex -lt 10; $tabIndex++) {
                $null = Invoke-Cdp 'Input.dispatchKeyEvent' @{type='keyDown'; key='Tab'; code='Tab'; windowsVirtualKeyCode=9}
                $null = Invoke-Cdp 'Input.dispatchKeyEvent' @{type='keyUp'; key='Tab'; code='Tab'; windowsVirtualKeyCode=9}
            }
            $focus = Invoke-Cdp 'Runtime.evaluate' @{expression='document.getElementById("old-student-login").contains(document.activeElement)'; returnByValue=$true}
            if (!$focus.result.value) { throw 'Keyboard focus escaped the login modal.' }
            $capture = Invoke-Cdp 'Page.captureScreenshot' @{format='png'; captureBeyondViewport=$false}
            [IO.File]::WriteAllBytes((Join-Path $PreviewDirectory ($viewport.name+'-login-modal.png')), [Convert]::FromBase64String($capture.data))
            $null = Invoke-Cdp 'Runtime.evaluate' @{expression='document.querySelector(".alumni-login-close").click()'}
            $closed = Invoke-Cdp 'Runtime.evaluate' @{expression='!document.getElementById("old-student-login").open&&document.activeElement.matches("button[data-open-login]")&&!document.documentElement.classList.contains("alumni-login-open")'; returnByValue=$true}
            if (!$closed.result.value) { throw 'Login modal close/focus restoration failed.' }
            $null = Invoke-Cdp 'Runtime.evaluate' @{expression='document.querySelector("button[data-open-login]").click()'}
            $null = Invoke-Cdp 'Input.dispatchKeyEvent' @{type='keyDown'; key='Escape'; code='Escape'; windowsVirtualKeyCode=27}
            $null = Invoke-Cdp 'Input.dispatchKeyEvent' @{type='keyUp'; key='Escape'; code='Escape'; windowsVirtualKeyCode=27}
            $escape = Invoke-Cdp 'Runtime.evaluate' @{expression='!document.getElementById("old-student-login").open'; returnByValue=$true}
            if (!$escape.result.value) { throw 'Escape did not close the login modal.' }
            $null = Invoke-Cdp 'Runtime.evaluate' @{expression='document.querySelector("button[data-open-login]").click()'}
            $null = Invoke-Cdp 'Input.dispatchMouseEvent' @{type='mousePressed'; x=1; y=1; button='left'; clickCount=1}
            $null = Invoke-Cdp 'Input.dispatchMouseEvent' @{type='mouseReleased'; x=1; y=1; button='left'; clickCount=1}
            $outside = Invoke-Cdp 'Runtime.evaluate' @{expression='!document.getElementById("old-student-login").open'; returnByValue=$true}
            if (!$outside.result.value) { throw 'Outside click did not close the login modal.' }
            $reopen = Invoke-Cdp 'Runtime.evaluate' @{expression='(async()=>{location.hash="old-student-login";await new Promise(r=>setTimeout(r,50));return document.getElementById("old-student-login").open;})()'; returnByValue=$true; awaitPromise=$true}
            if (!$reopen.result.value) { throw 'Login return hash did not reopen the modal.' }
            $null = Invoke-Cdp 'Runtime.evaluate' @{expression='document.querySelector(".alumni-login-close").click(); scrollTo(0,0)'}
            Write-Output "$($viewport.name): login popup, focus, close button, Escape, outside click and error-return hash passed."
        }
        $documentsCheck = Invoke-Cdp 'Runtime.evaluate' @{expression='!!document.getElementById("document-service")'; returnByValue=$true}
        if ($documentsCheck.result.value) {
            $documentState = Invoke-Cdp 'Runtime.evaluate' @{expression='(()=>{const s=document.getElementById("document-service"),d=document.getElementById("document-delivery");s.value="1";s.dispatchEvent(new Event("change"));d.value="physical";d.dispatchEvent(new Event("change"));return !document.querySelector("[data-delivery-fields=physical]").hidden&&document.querySelector("[data-delivery-fields=email]").hidden&&document.getElementById("document-total").textContent.includes("225.00");})()'; returnByValue=$true}
            if (!$documentState.result.value) { throw 'Document physical delivery fields or fee preview failed.' }
            $null = Invoke-Cdp 'Runtime.evaluate' @{expression='document.getElementById("document-request-form").scrollIntoView()'}
            $documentShot = Invoke-Cdp 'Page.captureScreenshot' @{format='png'; captureBeyondViewport=$false}
            [IO.File]::WriteAllBytes((Join-Path $PreviewDirectory "$($viewport.name)-document-form.png"),[Convert]::FromBase64String($documentShot.data))
            $documentEmail = Invoke-Cdp 'Runtime.evaluate' @{expression='(()=>{const s=document.getElementById("document-service"),d=document.getElementById("document-delivery");d.value="email";d.dispatchEvent(new Event("change"));const email=!document.querySelector("[data-delivery-fields=email]").hidden&&document.querySelector("[data-delivery-fields=physical]").hidden&&document.getElementById("document-total").textContent.includes("200.00");s.value="3";s.dispatchEvent(new Event("change"));return email&&d.value===""&&d.querySelector("option[value=email]").disabled&&document.documentElement.scrollWidth<=innerWidth+1;})()'; returnByValue=$true}
            if (!$documentEmail.result.value) { throw 'Document delivery switching or permitted methods failed.' }
            $null = Invoke-Cdp 'Runtime.evaluate' @{expression='scrollTo(0,0)'}
            Write-Output "$($viewport.name): document delivery fields, permitted methods and fees passed."
        }
        $studentCheck = Invoke-Cdp 'Runtime.evaluate' @{expression='!!document.querySelector(".wac-student-table")'; returnByValue=$true}
        if ($studentCheck.result.value) {
            $null = Invoke-Cdp 'Runtime.evaluate' @{expression='document.getElementById("matches-heading").scrollIntoView(); document.querySelector(".wac-evidence summary").click();'}
            $state = Invoke-Cdp 'Runtime.evaluate' @{expression='document.querySelector(".wac-evidence").open && document.documentElement.scrollWidth <= innerWidth+1'; returnByValue=$true}
            if (!$state.result.value) { throw 'Student evidence expansion failed or overflowed.' }
            $capture = Invoke-Cdp 'Page.captureScreenshot' @{format='png'; captureBeyondViewport=$false}
            [IO.File]::WriteAllBytes((Join-Path $PreviewDirectory ($viewport.name+'-students.png')), [Convert]::FromBase64String($capture.data))
            $null = Invoke-Cdp 'Runtime.evaluate' @{expression='document.querySelector(".wac-evidence summary").click(); window.dispatchEvent(new Event("beforeprint"));'}
            $printState = Invoke-Cdp 'Runtime.evaluate' @{expression='[...document.querySelectorAll(".wac-evidence")].every(d=>d.open)'; returnByValue=$true}
            if (!$printState.result.value) { throw 'Print did not expand student evidence.' }
            $null = Invoke-Cdp 'Runtime.evaluate' @{expression='window.dispatchEvent(new Event("afterprint")); scrollTo(0,0);'}
            Write-Output "$($viewport.name): student evidence and print expansion passed."
        }
        $achievementCheck = Invoke-Cdp 'Runtime.evaluate' @{expression='!!document.getElementById("student-achievement")'; returnByValue=$true}
        if ($achievementCheck.result.value) {
            $null = Invoke-Cdp 'Runtime.evaluate' @{expression='document.getElementById("student-achievement").scrollIntoView()'}
            $capture = Invoke-Cdp 'Page.captureScreenshot' @{format='png'; captureBeyondViewport=$false}
            [IO.File]::WriteAllBytes((Join-Path $PreviewDirectory ($viewport.name+'-achievement.png')), [Convert]::FromBase64String($capture.data))
            $null = Invoke-Cdp 'Runtime.evaluate' @{expression='scrollTo(0,0)'}
        }
        $workspaceCheck = Invoke-Cdp 'Runtime.evaluate' @{expression='!!document.querySelector("[data-waec-workspace]")'; returnByValue=$true}
        if ($workspaceCheck.result.value) {
            foreach($panel in @('waec-overview','waec-subjects','student-result-analysis','waec-coverage','waec-upload')) {
                $expression = "(async()=>{ document.querySelector('[data-waec-nav][href=\""#$panel\""]').click(); await new Promise(r=>setTimeout(r,30)); const visible=[...document.querySelectorAll('.waec-panel')].filter(p=>!p.hidden); return JSON.stringify({active:visible.map(p=>p.id), width:innerWidth, content:document.documentElement.scrollWidth}); })()"
                $state = Invoke-Cdp 'Runtime.evaluate' @{expression=$expression; returnByValue=$true; awaitPromise=$true}
                $panelState = $state.result.value | ConvertFrom-Json
                if ($panelState.active.Count -ne 1 -or $panelState.active[0] -ne $panel) { throw "Panel navigation failed: $panel" }
                if ($panelState.content -gt ($panelState.width+1)) { throw "Panel overflow: $panel" }
                $capture = Invoke-Cdp 'Page.captureScreenshot' @{format='png'; captureBeyondViewport=$false}
                [IO.File]::WriteAllBytes((Join-Path $PreviewDirectory ($viewport.name+'-'+$panel+'.png')), [Convert]::FromBase64String($capture.data))
            }
            Write-Output "$($viewport.name): all five workspace sections switch correctly without overflow."
            $null = Invoke-Cdp 'Runtime.evaluate' @{expression='location.hash="waec-overview"; scrollTo(0,0)'}
        }
    }
    $pdf = Invoke-Cdp 'Page.printToPDF' @{landscape=$true; printBackground=$true; preferCSSPageSize=$true}
    [IO.File]::WriteAllBytes((Join-Path $PreviewDirectory 'comparison-checked.pdf'), [Convert]::FromBase64String($pdf.data))
    Write-Output 'Print-to-PDF completed for the synthetic report.'
} finally {
    if ($socket) { $socket.Dispose() }
    if ($browserProcess -and !$browserProcess.HasExited) { Stop-Process -Id $browserProcess.Id }
}
